        [TestMethod]
        public void Do_Not_Implement_Any_Method_Which_Represents_Not_An_Http_Endpoint()
        {
            var noSecurity = (from controller in Controllers
                              from method in controller.Methods
                              where method.Attributes.All(a => a.Name.StartWith("Http").IsFalse())
                              select new
                              {
                                  ErrorClass = controller.FullQualifiedName,
                                  Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
MethodName: {method.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:     

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:     

[HttpPost]
[ProducesResponseType(typeof(AddUserResponse), StatusCodes.Status200OK)]
[ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest)]
public Task<AddUserResponse> AddUserAsync(User user,
                                      CancellationToken cancellationToken = default)
{{
    return _mediator.SendAsync(new AddUser(user), cancellationToken);
}}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                              }).ToImmutableList();


            Assert.IsTrue(noSecurity.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00014

Please implement only method which are representing an http action. If you need helper methods or logic this is not the place to be. Findings {noSecurity.Count}': {Environment.NewLine}{noSecurity.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
